# Check all FC weights > 0.65
fc_w = W['fc.weight']
print("FC weights > 0.65:")
for c in range(10):
    for f in range(64):
        val = fc_w[c, f].item()
        if val > 0.65:
            print(f"  Class {c} ({CLASSES[c]}), Feature {f}: {val:.4f}")

# Also check the second highest for auto and ship
print("\nTop 3 weights per class:")
for c in range(10):
    top3 = fc_w[c].topk(3)
    print(f"  Class {c} ({CLASSES[c]}): {[(idx.item(), val.item()) for idx, val in zip(top3.indices, top3.values)]}")
